fn ts_boundary_template(args: &[Value], natives: &[lash_kernel_doc::PreparedNative]) -> Option<Value> {
    let _ = natives;
    match args {
        [Value::Float(_) | Value::Text(_)] => {
            if let Some(value) = (|| {
                Some(args[0])
            })() { return Some(value); }
            None
        },
        _ => None,
    }
}
fn ts_boundary_heap(heap: &mut dyn p::TemplateHeap, args: &[Value], natives: &[lash_kernel_doc::PreparedNative]) -> Option<Value> {
    let _ = (&heap, natives);
    match args {
        [Value::LongText(_)] => {
            heap.path();
            if let Some(value) = (|| {
                heap.bind(Value::Text(lash_kernel_doc::arena::ShortText::new("text")?), None)?;
                Some(args[0])
            })() { return Some(value); }
            None
        },
        _ => None,
    }
}

